// ********************************************************
// Imports
// ********************************************************

import React from 'react';
import { connect } from 'react-redux';
import { Row, Col, Container, OverlayTrigger, Tooltip } from 'react-bootstrap';

import UiCtrl2d from './UiCtrl2d';
import Graphics2d from '../engine/Graphics2d';
import UiTools2d from './UiTools2d';
// import UiSegm2d from './UiSegm2d';
import UiVolumeSel from './UiVolumeSel'

// import UiHistCard from './UiHistCard';

// ********************************************************
// Const
// ********************************************************

// ********************************************************
// Class
// ********************************************************

/**
 * Class UiMain2d some text later...
 */
class UiMain2d extends React.Component {

  constructor(props) {
    super(props);
    this.state = { horizontal: false, vertical: false, mirrorStyle:{ justifyContent:'center',display:'flex' } };
  }

  transferFuncCallback(transfFuncObj) {
    const i = transfFuncObj.m_indexMoved;
    const x = transfFuncObj.m_handleX[i];
    const y = transfFuncObj.m_handleY[i];
    console.log(`moved point[${i}] = ${x}, ${y}  `);
  }




  onVertical = () => {
    if(this.state.vertical){
      this.setState({
        vertical: false,
        mirrorStyle: { justifyContent:'center',display:'flex' }
      })
    }else{
      this.setState({
        vertical: true,
        horizontal: false,
        mirrorStyle: { WebkitTransform:'scale(1, -1)',OTransform:'scale(1, -1)',MsTransform:'scale(1, -1)',transform:'scale(1, -1)', justifyContent:'center',display:'flex' }
      })

    }
  }

  onHorizontal = () => {
    if(this.state.horizontal){
      this.setState({
        horizontal: false,
        mirrorStyle: { justifyContent:'center',display:'flex' }
      })
    }else{
      this.setState({
        vertical: false,
        horizontal: true,
        mirrorStyle: { MozTransform:'scale(-1, 1)',WebkitTransform:'scale(-1, 1)',OTransform:'scale(-1, 1)',MsTransform:'scale(-1, 1)',transform:'scale(-1, 1)',justifyContent:'center',display:'flex' }
      })
    }
  }

  /*
   *
   * Main component render func callback
   */
  render() {
    // const MIN_HEIGHT = 800;
    // const strMinHeight = {
    //   minHeight: MIN_HEIGHT.toString() + 'px'
    // };
    const store = this.props;
    // const dicomSeries = store.dicomSeries;
    // const numSer = dicomSeries.length;
    const volSet = store.volumeSet;
    const vols = volSet.m_volumes;
    const numVols = vols.length;
    const jsxVolSel = (numVols > 1) ? <UiVolumeSel /> : <br />

    
    const jsxMain2d = 
      <Container fluid style={{ height:'90vh', minHeight:'90vh' }} >
        <Row>
          
          <Col xs md lg="4" style={{ height:'90vh' }} >

            <UiCtrl2d />
            <UiTools2d />
            <div className="card bg-dark text-white">
              <div className="card-header">
                Orientacion (Espejo) 
              </div>
              <div className="card-body">
              <OverlayTrigger key={'Vertical'} placement="bottom" overlay={
                  <Tooltip>
                    Vertical
                  </Tooltip>
                }>
              <button type='button' className="col-2 btn btn-outline-secondary"  onClick={this.onVertical} >
                  <img className='img-thumbnail' src={'visor3d/images/vertical.png'}  />
              </button>
            </OverlayTrigger>
            <OverlayTrigger key={'Horizontal'} placement="bottom" overlay={
                <Tooltip>
                  Horizontal
                </Tooltip>
              }>
              <button type='button' className="col-2 btn btn-outline-secondary"  onClick={this.onHorizontal} >
                  <img className='img-thumbnail' src={'visor3d/images/horizontal.png'} />
              </button> 
            </OverlayTrigger>
                
                
              </div>
            </div>
            {/* <UiSegm2d /> */}
            {jsxVolSel}

            { /*            
            <UiHistCard volume={vol} transfFunc={funcTra} />
            */ }
            
          </Col>
          {/* <Col xs md lg="8" style={strMinHeight} > */}
          <Col xs md lg="8" style={ this.state.mirrorStyle } >
            <Graphics2d   />
          </Col>
        </Row>
      </Container>

    return jsxMain2d;
  };
}

export default connect(store => store)(UiMain2d);
